export function foreignScafAacFixture(variant: keyof typeof ENCODED): Readonly<{ file: File; channels: readonly Float32Array[] }> {
	const bytes = Uint8Array.from(inflateSync(Buffer.from(ENCODED[variant], 'base64')));
	assert.equal(createHash('sha256').update(bytes).digest('hex'), SHA256[variant]);
	const reference = inflateSync(Buffer.from(REFERENCE, 'base64'));
	assert.equal(reference.length, 5120 * 2 * 4);
	return { file: new File([bytes.buffer], `${variant}.m4a`, { type: 'audio/mp4' }),
		channels: [0, 1].map(channel => Float32Array.from({ length: 4800 }, (_, frame) => reference.readFloatLE((frame * 2 + channel) * 4))) };
}
